table account_tokens :: CREATE TABLE account_tokens ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL )
table admin_audit :: CREATE TABLE admin_audit ( id TEXT PRIMARY KEY, admin_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL )
table appeals :: CREATE TABLE appeals ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, audit_id TEXT NOT NULL, sanctioner_id TEXT, sanction_reason TEXT NOT NULL DEFAULT '', sanction_at TEXT, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', reviewer_id TEXT REFERENCES users(id), resolution TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, resolved_at TEXT , reviewed_by_kind TEXT NOT NULL DEFAULT 'staff', reviewed_by_name TEXT)
table auth_attempts :: CREATE TABLE auth_attempts ( id INTEGER PRIMARY KEY AUTOINCREMENT, attempt_key TEXT NOT NULL, created_at TEXT NOT NULL )
table availability_alerts :: CREATE TABLE availability_alerts ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, city TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (user_id, city) )
table blocks :: CREATE TABLE blocks ( blocker_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY (blocker_id, blocked_id) )
table book_comment_likes :: CREATE TABLE book_comment_likes ( comment_id TEXT NOT NULL REFERENCES book_comments(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY (comment_id, user_id) )
table book_comments :: CREATE TABLE book_comments ( id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE, author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, parent_id TEXT REFERENCES book_comments(id) ON DELETE CASCADE, body TEXT NOT NULL, spoiler INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'visible', created_at TEXT NOT NULL )
table book_wants :: CREATE TABLE book_wants ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE, created_at TEXT NOT NULL, last_notified_at TEXT, PRIMARY KEY (user_id, book_id) )
table books :: CREATE TABLE books ( id TEXT PRIMARY KEY, title TEXT NOT NULL, title_key TEXT NOT NULL, author TEXT NOT NULL, isbn TEXT UNIQUE, category TEXT NOT NULL, cover_url TEXT, created_at TEXT NOT NULL , language TEXT NOT NULL DEFAULT 'No especificado', work_key TEXT, publisher TEXT, year TEXT, series TEXT, description TEXT, pages INTEGER, work_id TEXT REFERENCES works(id))
table books_fts :: CREATE VIRTUAL TABLE books_fts USING fts5( title, author, content='books', content_rowid='rowid', tokenize='unicode61 remove_diacritics 2' )
table books_fts_config :: CREATE TABLE 'books_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID
table books_fts_data :: CREATE TABLE 'books_fts_data'(id INTEGER PRIMARY KEY, block BLOB)
table books_fts_docsize :: CREATE TABLE 'books_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)
table books_fts_idx :: CREATE TABLE 'books_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID
table cities :: CREATE TABLE cities ( name TEXT PRIMARY KEY, lat REAL NOT NULL, lng REAL NOT NULL )
table city_distances :: CREATE TABLE city_distances ( from_name TEXT NOT NULL, to_name TEXT NOT NULL, km REAL NOT NULL, PRIMARY KEY (from_name, to_name) )
table club_attendance :: CREATE TABLE club_attendance ( club_id TEXT NOT NULL REFERENCES clubs(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, meets_key TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (club_id, user_id, meets_key) )
table club_loans :: CREATE TABLE club_loans ( id TEXT PRIMARY KEY, club_id TEXT NOT NULL REFERENCES clubs(id) ON DELETE CASCADE, listing_id TEXT NOT NULL REFERENCES listings(id) ON DELETE CASCADE, lender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, borrower_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, due_at TEXT, returned_at TEXT, created_at TEXT NOT NULL )
table club_members :: CREATE TABLE club_members ( club_id TEXT NOT NULL REFERENCES clubs(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, joined_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'member', role TEXT NOT NULL DEFAULT 'member', PRIMARY KEY (club_id, user_id) )
table club_poll_options :: CREATE TABLE club_poll_options ( id TEXT PRIMARY KEY, poll_id TEXT NOT NULL REFERENCES club_polls(id) ON DELETE CASCADE, book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE, position INTEGER NOT NULL DEFAULT 0 )
table club_poll_votes :: CREATE TABLE club_poll_votes ( poll_id TEXT NOT NULL REFERENCES club_polls(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, option_id TEXT NOT NULL REFERENCES club_poll_options(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY (poll_id, user_id) )
