table club_post_envelopes :: CREATE TABLE club_post_envelopes ( post_id TEXT NOT NULL REFERENCES club_posts(id) ON DELETE CASCADE, recipient_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient_device_id TEXT NOT NULL, type INTEGER, body TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (post_id, recipient_device_id) )
table club_post_likes :: CREATE TABLE club_post_likes ( post_id TEXT NOT NULL REFERENCES club_posts(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY (post_id, user_id) )
table club_posts :: CREATE TABLE club_posts ( id TEXT PRIMARY KEY, club_id TEXT NOT NULL REFERENCES clubs(id) ON DELETE CASCADE, author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, parent_id TEXT REFERENCES club_posts(id) ON DELETE CASCADE, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'visible', created_at TEXT NOT NULL , encrypted INTEGER NOT NULL DEFAULT 0, sender_device_id TEXT)
table clubs :: CREATE TABLE clubs ( id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, city TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', book_id TEXT REFERENCES books(id) ON DELETE SET NULL, meets_on TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL , meets_at TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'visible', join_policy TEXT NOT NULL DEFAULT 'open', progress INTEGER NOT NULL DEFAULT 0, progress_note TEXT NOT NULL DEFAULT '', meets_place TEXT NOT NULL DEFAULT '', meets_link TEXT NOT NULL DEFAULT '')
table device_keys :: CREATE TABLE device_keys ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id TEXT NOT NULL, identity_key TEXT NOT NULL, signing_key TEXT NOT NULL, bundle_signature TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, revoked_at TEXT, PRIMARY KEY (user_id, device_id) )
table device_one_time_keys :: CREATE TABLE device_one_time_keys ( user_id TEXT NOT NULL, device_id TEXT NOT NULL, key_id TEXT NOT NULL, key TEXT NOT NULL, signature TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (user_id, device_id, key_id), FOREIGN KEY (user_id, device_id) REFERENCES device_keys(user_id, device_id) ON DELETE CASCADE )
table dm_message_envelopes :: CREATE TABLE dm_message_envelopes ( message_id TEXT NOT NULL REFERENCES dm_messages(id) ON DELETE CASCADE, key_id TEXT NOT NULL, ciphertext TEXT NOT NULL, iv TEXT NOT NULL, protocol INTEGER NOT NULL DEFAULT 1, type INTEGER, PRIMARY KEY (message_id, key_id) )
table dm_messages :: CREATE TABLE dm_messages ( id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES dm_threads(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL DEFAULT '', ciphertext TEXT, iv TEXT, key_id TEXT, encrypted INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL , sender_device_id TEXT)
table dm_reads :: CREATE TABLE dm_reads ( thread_id TEXT NOT NULL REFERENCES dm_threads(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, read_at TEXT NOT NULL, PRIMARY KEY (thread_id, user_id) )
table dm_threads :: CREATE TABLE dm_threads ( id TEXT PRIMARY KEY, user_a TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, user_b TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, last_message_at TEXT, UNIQUE (user_a, user_b) )
table events :: CREATE TABLE events ( id TEXT PRIMARY KEY, type TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), listing_id TEXT REFERENCES listings(id), request_id TEXT REFERENCES requests(id), created_at TEXT NOT NULL )
table favorites :: CREATE TABLE favorites ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, listing_id TEXT NOT NULL REFERENCES listings(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY (user_id, listing_id) )
table follows :: CREATE TABLE follows ( follower_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, followed_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY (follower_id, followed_id) )
table jobs :: CREATE TABLE jobs ( id TEXT PRIMARY KEY, kind TEXT NOT NULL, target TEXT, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT, created_at TEXT NOT NULL, finished_at TEXT )
table key_snapshots :: CREATE TABLE key_snapshots ( id TEXT PRIMARY KEY, created_at TEXT NOT NULL, item_count INTEGER NOT NULL, merkle_root TEXT NOT NULL, previous_root TEXT, payload BLOB, signature TEXT, public_key TEXT, signer TEXT )
table listing_tags :: CREATE TABLE listing_tags ( listing_id TEXT NOT NULL REFERENCES listings(id) ON DELETE CASCADE, tag TEXT NOT NULL, PRIMARY KEY (listing_id, tag) )
table listings :: CREATE TABLE listings ( id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), owner_id TEXT NOT NULL REFERENCES users(id), condition TEXT NOT NULL, city TEXT NOT NULL, distance_km REAL, status TEXT NOT NULL DEFAULT 'available', search_key TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL , notes TEXT NOT NULL DEFAULT '', moderated_from TEXT, from_listing_id TEXT, from_request_id TEXT)
table listings_fts :: CREATE VIRTUAL TABLE listings_fts USING fts5( search_key, content='listings', content_rowid='rowid', tokenize='unicode61 remove_diacritics 2' )
table listings_fts_config :: CREATE TABLE 'listings_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID
table listings_fts_data :: CREATE TABLE 'listings_fts_data'(id INTEGER PRIMARY KEY, block BLOB)
table listings_fts_docsize :: CREATE TABLE 'listings_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)
table listings_fts_idx :: CREATE TABLE 'listings_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID
table message_envelopes :: CREATE TABLE message_envelopes ( message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, key_id TEXT NOT NULL, ciphertext TEXT NOT NULL, iv TEXT NOT NULL, protocol INTEGER NOT NULL DEFAULT 1, type INTEGER, PRIMARY KEY (message_id, key_id) )
table messages :: CREATE TABLE messages ( id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL , ciphertext TEXT, iv TEXT, encrypted INTEGER NOT NULL DEFAULT 0, key_id TEXT, sender_device_id TEXT)
table notifications :: CREATE TABLE notifications ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', listing_id TEXT, request_id TEXT, read_at TEXT, created_at TEXT NOT NULL , book_id TEXT, link TEXT)
table product_events :: CREATE TABLE product_events ( id TEXT PRIMARY KEY, type TEXT NOT NULL, user_id TEXT, club_id TEXT, created_at TEXT NOT NULL )
table public_key_history :: CREATE TABLE public_key_history ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, key_id TEXT NOT NULL, public_jwk TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL, replaced_at TEXT , platform TEXT NOT NULL DEFAULT 'web')
table push_subscriptions :: CREATE TABLE push_subscriptions ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, user_agent TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL )
table reading_list_items :: CREATE TABLE reading_list_items ( list_id TEXT NOT NULL REFERENCES reading_lists(id) ON DELETE CASCADE, book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE, note TEXT NOT NULL DEFAULT '', added_at TEXT NOT NULL, PRIMARY KEY (list_id, book_id) )
table reading_lists :: CREATE TABLE reading_lists ( id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL , show_owner INTEGER NOT NULL DEFAULT 0)
table reading_states :: CREATE TABLE reading_states ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK (status IN ('reading', 'read')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, book_id) )
table reports :: CREATE TABLE reports ( id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id), target_type TEXT NOT NULL, target_id TEXT NOT NULL, reason TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL, response TEXT NOT NULL DEFAULT '', response_by TEXT, response_at TEXT )
table request_archives :: CREATE TABLE request_archives ( request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, archived_at TEXT NOT NULL, PRIMARY KEY (request_id, user_id) )
table request_reads :: CREATE TABLE request_reads ( request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, read_at TEXT NOT NULL, PRIMARY KEY (request_id, user_id) )
table requests :: CREATE TABLE requests ( id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES listings(id), requester_id TEXT NOT NULL REFERENCES users(id), owner_id TEXT NOT NULL REFERENCES users(id), message TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, updated_at TEXT NOT NULL , owner_confirmed_at TEXT, requester_confirmed_at TEXT, accepted_at TEXT)
table reviews :: CREATE TABLE "reviews" ( id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, author_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), rating INTEGER NOT NULL, comment TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE (request_id, author_id) )
table sessions :: CREATE TABLE sessions ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, -- Para poder enseñar las sesiones en la cuenta y cerrar una sola. user_agent TEXT NOT NULL DEFAULT '', last_seen_at TEXT )
table social_likes :: CREATE TABLE social_likes ( id TEXT PRIMARY KEY, network TEXT NOT NULL, status_id TEXT NOT NULL, account_acct TEXT NOT NULL, status_url TEXT, tag TEXT, locale TEXT, created_at TEXT NOT NULL, UNIQUE (network, status_id) )
table social_outbox :: CREATE TABLE social_outbox ( id TEXT PRIMARY KEY, network TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT, external_id TEXT, external_url TEXT, created_at TEXT NOT NULL, sent_at TEXT , media_id TEXT, owner_id TEXT, day TEXT)
table throttle :: CREATE TABLE throttle ( id INTEGER PRIMARY KEY AUTOINCREMENT, bucket TEXT NOT NULL, throttle_key TEXT NOT NULL, created_at TEXT NOT NULL )
table transparency_snapshots :: CREATE TABLE transparency_snapshots ( id TEXT PRIMARY KEY, created_at TEXT NOT NULL, item_count INTEGER NOT NULL, merkle_root TEXT NOT NULL, payload_hash TEXT NOT NULL, previous_root TEXT, payload BLOB, signature TEXT, public_key TEXT, signer TEXT )
table user_keys :: CREATE TABLE user_keys ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, platform TEXT NOT NULL, key_id TEXT NOT NULL, public_jwk TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, platform) )
table users :: CREATE TABLE users ( id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, city TEXT NOT NULL DEFAULT 'Stuttgart', bio TEXT NOT NULL DEFAULT '', notifications_seen_at TEXT, created_at TEXT NOT NULL, -- Visibilidad elegida por cada persona (v48). profile_visibility TEXT NOT NULL DEFAULT 'members', city_precision TEXT NOT NULL DEFAULT 'exact', sign_as TEXT NOT NULL DEFAULT 'name', dm_policy TEXT NOT NULL DEFAULT 'mutual' , is_admin INTEGER NOT NULL DEFAULT 0, is_suspended INTEGER NOT NULL DEFAULT 0, email_verified_at TEXT, totp_secret TEXT, totp_enabled_at TEXT, totp_last_step INTEGER, public_key TEXT, public_key_at TEXT, public_key_id TEXT, email_notifications INTEGER NOT NULL DEFAULT 1, locale TEXT NOT NULL DEFAULT 'es', is_moderator INTEGER NOT NULL DEFAULT 0, suspended_until TEXT, suspension_reason TEXT, show_journey INTEGER NOT NULL DEFAULT 1)
table works :: CREATE TABLE works ( id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, title TEXT NOT NULL, author TEXT NOT NULL, created_at TEXT NOT NULL )
trigger books_fts_ad :: CREATE TRIGGER books_fts_ad AFTER DELETE ON books BEGIN INSERT INTO books_fts(books_fts, rowid, title, author) VALUES ('delete', old.rowid, old.title, old.author); END
trigger books_fts_ai :: CREATE TRIGGER books_fts_ai AFTER INSERT ON books BEGIN INSERT INTO books_fts(rowid, title, author) VALUES (new.rowid, new.title, new.author); END
trigger books_fts_au :: CREATE TRIGGER books_fts_au AFTER UPDATE ON books BEGIN INSERT INTO books_fts(books_fts, rowid, title, author) VALUES ('delete', old.rowid, old.title, old.author); INSERT INTO books_fts(rowid, title, author) VALUES (new.rowid, new.title, new.author); END
trigger listings_fts_ad :: CREATE TRIGGER listings_fts_ad AFTER DELETE ON listings BEGIN INSERT INTO listings_fts(listings_fts, rowid, search_key) VALUES ('delete', old.rowid, old.search_key); END
trigger listings_fts_ai :: CREATE TRIGGER listings_fts_ai AFTER INSERT ON listings BEGIN INSERT INTO listings_fts(rowid, search_key) VALUES (new.rowid, new.search_key); END
trigger listings_fts_au :: CREATE TRIGGER listings_fts_au AFTER UPDATE ON listings BEGIN INSERT INTO listings_fts(listings_fts, rowid, search_key) VALUES ('delete', old.rowid, old.search_key); INSERT INTO listings_fts(rowid, search_key) VALUES (new.rowid, new.search_key); END
